int main() {
    int V, E;
    cin >> V >> E;
    vector<vector<pair<int, int>>> adj(V);
    for (int i = 0; i < E; i++) {
        int a, b, w; cin >> a >> b >> w;
        adj[a].push_back({b, w});
        adj[b].push_back({a, w});
    }
    int src; cin >> src;
    vector<int> d = dijkstra(adj, src);
    for (int i = 0; i < V; i++) cout << "dist[" << i << "] = " << d[i] << endl;
}

